    "resistor_colour_code_both": "رمز ألوان المقاومات في الاتجاهين، ورموز SMD وEIA-96، والعناصر على التوالي والتوازي، وقانون أوم، ومقاومة السلك ومقاسه AWG، ومقسم الجهد وثيفينن، وقنطرة ويتستون، ومقاومات الثنائيات الباعثة للضوء، والمكثفات، ودوائر RC وRL، والمرشحات من الرتبتين الأولى والثانية، والألواح المتوازية، والمحولات والتيار المتردد، والقدرة ثلاثية الطور، ومعاوقة R وL وC ورنينها، وتكلفة الكهرباء، وعمر البطارية؛ والثنائيات والمقومات وتموجها؛ والترانزستورات كمفاتيح ومنحازة، وMOSFET، وثنائيات زينر، وLM317، والمضخمات العملياتية، والمؤقت 555؛ وdBm وdBV وdBµV والكسب بالـ dB. تُكتب قيمة العنصر كما هي: 4.7k و4k7 و100n؛ والمقاومة المتاحة للشراء من E12.",
    "v_f_standing_waves": "v = fλ، والموجات الموقوفة في الأوتار والأنابيب، والضربات، والعدسات والمرايا، ومعادلة صانع العدسات، والانكسار والزاوية الحرجة، والتداخل عبر شقين أو محزوز حيود، والشق الواحد وقدرة تمييز العدسة، والاستقطاب، وظاهرة دوبلر في الصوت والضوء، والضوء والفوتونات، والصوت بالديسيبل.",
    "matter": "المادة",
    "heat_q_mc_t": "الحرارة: Q = mcΔT من أي ثلاثة، والحرارة الكامنة، والخلط، والتمدد الحراري، والتوصيل، والإشعاع، وقانون نيوتن للتبريد، ونقطة الندى، وسرعات جزيئات الغاز، والغاز المثالي في عملية متساوية الحرارة أو الضغط أو الحجم أو كظومة، والمحركات الحرارية. المواد الصلبة: الإجهاد والانفعال. الموائع: الكثافة، والضغط، والضغط على عمق، والطفو، والتدفق في أنبوب، وعدد رينولدز مع احتكاك الأنبوب، وقانون ستوكس.",
    "modern": "الفيزياء الحديثة",
    "e_mc_binding_energy": "E = mc²، وطاقة الربط، والقيمة Q للتفاعل، والظاهرة الكهروضوئية، وأطوال موجات دي برولي، ومبدأ عدم التأكد، وجسيم في صندوق، وتشتت كومبتون، والنفق الكمومي، والنسبية الخاصة، وخطوط الهيدروجين ومدارات بور، والاضمحلال الإشعاعي.",
    "biology": "الأحياء",
    "genetics_from_punnett_squares": "الوراثة، من مربعات بانيت إلى الخرائط الجينية والخطر الوراثي؛ والـDNA والـRNA، ترجمةً ومحاذاةً، مع البادئات وموجِّهات CRISPR والهلام؛ والبروتينات والإنزيمات؛ وتخفيفات المختبر وعدّه والـqPCR؛ والخلايا؛ والصحة؛ والبيئة والتطور. انقر عددًا لإدخاله.",
    "close_biology": "إغلاق الأحياء",
    "genetics": "الوراثة",
    "punnett_squares_of_up": "مربعات بانيت لما يصل إلى ستة جينات، مرسومة، وللصبغي X؛ وهاردي–واينبرغ، من p أو من الأعداد مع اختبار χ² أو من الصفة المتنحية؛ وχ² للتهجين؛ والخرائط الجينية لجينين أو ثلاثة، مع رسم الصبغي؛ واحتمالات النسل؛ والتوريث بمعادلة المربّي؛ والتفوق الجيني وأي نسبة تناسبه؛ والخطر الوراثي، مع رسم شجرة العائلة؛ وفصائل الدم.",
    "sequence_s_length_bases": "طول التسلسل وقواعده ونسبة GC على امتداده وكتلته، مع المتمم والمتمم العكسي؛ والترجمة في ستة أطر وأطر القراءة المفتوحة، مرسومة؛ وعجلة الكودونات؛ وT<sub>m</sub> للبادئة بطريقة الجيران الأقرب، مع رسم انصهاره؛ والـDNA والـRNA من A<sub>260</sub> ونقاوتهما؛ والكتلة والمولات والنسخ؛ والربط، مع رسم البلازميد؛ وهضم إنزيمات القطع على الهلام؛ ونسخ الـPCR دورةً بدورة؛ والمحاذاة الكلية والموضعية مع مخطط النقاط؛ وموجِّهات CRISPR؛ والأنماط برموز IUPAC؛ وبادئات الطفرات وتجميع غيبسون؛ والجينومات ونسخها.",
    "protein_s_mass_pi": "كتلة البروتين ونقطته المتعادلة pI وشحنته ومعامل امتصاصه وكره الماء فيه، مرسومة؛ والأحماض الأمينية العشرون، مع رسم معايرة كل منها؛ وتركيز البروتين من A<sub>280</sub> أو من منحنى معياري؛ وحركية الإنزيمات، من V<sub>max</sub> وK<sub>m</sub> أو بمطابقة النقاط، مع المثبطات ومخطط لاينويفر–بيرك؛ والارتباط بمعادلة هِل؛ والجرعة والاستجابة مع مطابقة IC<sub>50</sub>؛ وجدول التنقية.",
    "lab": "المختبر",
    "c_v_c_v": "C₁V₁ = C₂V₂ والتخفيفات المتسلسلة، مع رسم أنابيبها؛ وتحضير محلول من مولاريته أو صيغته أو نسبته المئوية أو من محلول أصلي؛ وعدّ الخلايا؛ والنمو وزمن التضاعف وOD<sub>600</sub>؛ والمستعمرات وCFU/mL؛ وسرعة الطرد المركزي RPM وg؛ وخليط الـPCR الرئيسي؛ والـqPCR بطريقة ΔΔCt ومنحناه المعياري؛ والمتوسط ± 2 SE مع أعمدة الخطأ؛ وR<sub>f</sub> في الكروماتوغرافيا؛ والمجهر؛ والأحجام من الهلام؛ وكفاءة التحويل؛ وزرع الأطباق؛ وMOI؛ والنظائر المشعة؛ والمحاليل المنظمة.",
    "water_potential_osmolarity_and": "الجهد المائي والأسمولية والتوتر، مع رسم خلية دم حمراء؛ ونسبة المساحة إلى الحجم؛ وQ₁₀؛ والانتشار بقانون فيك؛ وجهود الغشاء بمعادلتي نيرنست وغولدمان؛ والطاقة الحرة؛ ونتاج القلب وضغط الدم، مرسومًا؛ والتنفس الخلوي وATP الناتج والحاصل التنفسي.",
    "health": "الصحة",
    "diagnostic_tests_their_sensitivity": "الاختبارات التشخيصية وحساسيتها ونوعيتها وقيمها التنبؤية، مع رسم ألف شخص؛ ونسب الخطر والأرجحية مع فتراتها، والعدد اللازم علاجه؛ والوباء بنموذج SIR ومناعة القطيع؛ والأكسجين والهيموغلوبين، مع رسم إزاحة بور؛ وجهد الفعل بنموذج هودجكن وهكسلي؛ والكليتان وeGFR والتصفية؛ ومؤشر كتلة الجسم والطاقة؛ ومستويات الدواء عبر جرعاته. للتعلّم، لا للعلاج.",
