    "what_toolbar_icon_and": "ما تفتحه أيقونة شريط الأدوات وAlt+S: ثابت، النافذة المنبثقة تحت الأيقونة؛ أو منفصل، الحاسبة في نافذة مستقلة تكبر وتصغر معها؛ أو متقدم، الحاسبة في نافذة كبيرة والأدوات على جانبها، وزر الإعادة فيها يرجعها إلى الوضع المنفصل. ويفتح زر التشغيل الوضع المختار؛ والوضعان المنفصل والمتقدم موجودان أيضًا في قائمة أيقونة شريط الأدوات، والمنفصل في زر الصفحة.",
