    "and_hill_slope_drawn": "وميل هِل، مرسومة؛ وجدول التنقية، مع النشاط النوعي والمردود ومعامل التنقية لكل خطوة.",
    "lab_c_v_c": "المختبر: C₁V₁ = C₂V₂ والتخفيفات المتسلسلة، مع رسم الأنابيب؛ وتحضير محلول من مولارية، أو من كتلة مولية أو صيغة، أو نسبة مئوية، أو محلول أصلي؛ وعدّ الخلايا بعدّاد الكريات، مع الحيوية والزرع؛ والنمو وأزمنة التضاعف، وOD",
    "colonies_and_cfu_ml": "؛ والمستعمرات وCFU/mL، مع رسم الطبق؛ وRPM وg لجهاز الطرد المركزي؛ وخليط الـPCR الرئيسي؛ والـqPCR بطريقتي ΔΔCt وPfaffl، ومنحناه المعياري وكفاءته؛ والمتوسط ± 2 SE للمجموعات، مع أعمدة الخطأ؛ وR",
    "of_chromatography_microscope_s": "في الكروماتوغرافيا؛ وتكبير المجهر ومجال رؤيته؛ وحجم شريط من الهلام، للـDNA أو لبروتين على SDS-PAGE؛ وكفاءة التحويل؛ وزرع الأطباق، مع رسم الطبق؛ وMOI، والخلايا المصابة بتوزيع بواسون؛ والنظائر المشعة، واضمحلالها والوقاية منها؛ والمحاليل المنظمة، وما يُوزن وكم يُضاف من الحمض أو القاعدة.",
    "cells_water_potential_and": "الخلايا: الجهد المائي، وفي أي اتجاه يتحرك الماء؛ والأسمولية والتوتر، مع رسم خلية دم حمراء؛ ونسبة المساحة إلى الحجم؛ وQ",
    "diffusion_by_fick_s": "؛ والانتشار بقانون فيك، وزمن الانتشار؛ وجهود الأغشية بمعادلتي نيرنست وغولدمان، على مقياس بالـmV؛ والطاقة الحرة وK؛ ونتاج القلب وضغط الدم، مع رسم موجته؛ والتنفس الخلوي، وATP الناتج والحاصل التنفسي.",
    "health_diagnostic_tests_their": "الصحة: الاختبارات التشخيصية، وحساسيتها ونوعيتها وقيمها التنبؤية، مع رسم ألف شخص؛ ونسب الخطر والأرجحية مع فترات 95% والعدد اللازم علاجه؛ والوباء بنموذج SIR، ومناعة القطيع؛ والأكسجين والهيموغلوبين، مع رسم إزاحة بور؛ وجهد الفعل بنموذج هودجكن وهكسلي؛ والكليتان، وeGFR بمعادلة CKD-EPI 2021، والتصفية والأسمولالية؛ ومؤشر كتلة الجسم والطاقة؛ ومستويات الدواء عبر جرعاته. للتعلّم، لا للعلاج.",
    "ecology_population_growth_exponential": "البيئة: نمو الجماعات، الأسّي واللوجستي؛ والمفترس والفريسة بنموذج لوتكا وفولتيرا، مع رسم دوراتهما؛ والوسم وإعادة الصيد، بطريقتي لينكولن وبيترسن وتشابمان؛ والتنوع بمؤشري سيمبسون وشانون؛ وجداول الحياة ومنحنى البقاء؛ وأهرامات الطاقة؛ والإنتاجية الأولية بطريقة القوارير المضيئة والمعتمة؛ والانتخاب الطبيعي والانجراف الوراثي، جيلًا بعد جيل؛ ومصفوفات ليزلي؛ والتنافس بنموذج لوتكا وفولتيرا، مع خطوط التوازن؛ ومنحنيات الأنواع والمساحة، والتخلخل وChao1؛ والأشجار بطريقتي UPGMA وضمّ الجيران، من المسافات أو من تسلسلات محاذاة، مرسومة؛ والساعة الجزيئية، بطريقتي جوكس وكانتور وكيمورا.",
    "in_f_x_formulas": "وفي f(x) صيغ الأحياء والصحة، ولكلٍّ زر «في الأحياء» يفتح بطاقتها؛ وفي المحوّل المولارية، والتركيز الكتلي، وكمية المادة، والكتلة الجزيئية، وطول التسلسل، والنشاط الإنزيمي، والعدد لكل حجم، وجرعات الإشعاع.",
    "using_calculator": "استخدام الحاسبة",
    "click_on_numbers_and": "انقر الأعداد والدوال في الحاسبة كما تفعل في أي حاسبة عادية.",
    "display_shows_equation_as": "تعرض الشاشة المعادلة أثناء إدخالها، فترى دائمًا العملية التي ستُجرى. انقر علامة المساواة فتعرض الشاشة النتيجة، والمعادلة المكتملة في السطر الصغير فوقها. ويبقى حول زر فتح القوس إطار حتى تُغلق كل الأقواس.",
    "if_equation_gets_too": "إذا طالت المعادلة عن الشاشة، يصغر خطها أولًا. وبعد ذلك اضغط على السطر وأبقِه لحظة، ثم اسحبه يمينًا أو يسارًا لترى الباقي؛ وتدل النقاط (…) على الجانب الذي يختفي فيه المزيد. والسحب دون الإبقاء يحدد جزءًا منها. وفي شاشة اللمس، السحب يزلقها، والضغط المطول يحدد.",
    "if_calculation_not_possible": "إذا لم تكن العملية ممكنة (مثل 1 ÷ 0)، تعرض الشاشة Error ويعرض السطر الذي فوقها المعادلة التي سببته.",
    "calculator_uses_algebraic_method": "تستخدم هذه الحاسبة طريقة إدخال جبرية تتيح لك إدخال العمليات الرياضية بالترتيب الذي تُكتب به جبريًّا (PEMDAS / AOS™).",
    "pemdas_parentheses_exponents_multiplication": "PEMDAS: \"الأقواس، ثم الأسس، ثم الضرب أو القسمة، ثم الجمع أو الطرح\". والضرب والقسمة في المرتبة نفسها. وكذلك الجمع والطرح.",
    "keyboard_support": "دعم لوحة المفاتيح",
    "there_full_keyboard_support": "لكل زر في الحاسبة مفتاح على لوحة المفاتيح.",
