    "keys_same_on_keyboard": "المفاتيح هي نفسها على لوحة مفاتيح بلا حروف لاتينية، عربية أو عبرية أو روسية أو يونانية: كل مفتاح يعطي ما يعطيه المفتاح الذي في مكانه على لوحة المفاتيح الأمريكية، فـ[s] هو sin على مفتاح س، وShift+A،",
    "and_digits_work_as": "والأرقام تعمل كما تعمل في أي لوحة أخرى. وخانات اللوحات، في المحوّل والصيغ والرسم البياني، تأخذها بالطريقة نفسها: ٥ تكتب 5، وShift+ش تكتب A، والعدد الملصق ٣٫٥ يُقرأ 3.5.",
