    "ctrl_v_pastes_number": "يلصق Ctrl+V عددًا (1,234.5 و1.234,5 و1 234,5 كلها تُقرأ 1234.5؛ و1.234 وحدها تُقرأ بالفاصلة العشرية التي تحددها الخيارات، و$1,200 أو 5 USD تُقرأ عددًا وحده) أو معادلة كاملة، مثل 2 + 3 × sin(30) أو sqrt(16) + 2^3. وإن احتوى النص الملصق علامة مساواة، يُحسب فورًا.",
