    "right_click_display_for": "انقر الشاشة بالزر الأيمن لقائمة فيها القص والنسخ واللصق، وإعادة ضبط الكل، التي تبدأ الحاسبة من جديد: تمسح المعادلة والذاكرة، وتوقف 2nd والكسور و°′″، وتضبط Rad، وتمسح ما كُتب في الإحصاء وبحث الصيغ والمحوّل والرسم البياني والحل والأعداد؛ ويبقى السجل ومتغيراته. والنسخ يأخذ الجزء الذي حددته من الشاشة، وإلا فالنتيجة. وأول مرة تستخدم فيها اللصق هناك، يطلب المتصفح أن تسمح للحاسبة بقراءة ما نسخته؛ وCtrl+V يعمل دون ذلك. وللسجل والصيغ والمحوّل والإحصاء القائمة أيضًا: القص والنسخ واللصق وتحديد الكل في خانة تكتب فيها، والنسخ والإدراج على قيمة.",
