    "history_click_clock_at_2": "السجل: انقر الساعة أعلى يسار الشاشة لترى العمليات التي أنهيتها بـ'='. أشر إلى معادلة أو نتيجة ليظهر زراها على اليسار: الإدراج يُدخل المعادلة من جديد، لتعدّلها أو تنهيها بـ'='، أو يضع النتيجة عددًا في المعادلة التي تُدخلها؛ والنسخ ينسخها. والعملية التي فيها",
