    "f_turns_fraction_mode": "[f] يشغّل وضع الكسور ويوقفه. وما دام يعمل (FRAC في الشاشة)، تُرسم كل قسمة كسرًا أثناء كتابتها: 1 ÷ 2 + 1 ÷ 3 تظهر ½ + ⅓، و= تعرض 5/6. وتكون النتائج كسورًا متى أمكن، حتى 10 أرقام؛ والعدد الذي لا يكون كسرًا، مثل π أو √2، يبقى عشريًّا. والنسخ يعطي الكسر بالشكل 5/6. ويبقى الوضع مفعّلًا حتى تنقر",
